package com.primehr.succession.application;

import com.primehr.integration.administrative.PermissionDataScope;
import com.primehr.learningdevelopment.completion.domain.LdCompletionCase;
import com.primehr.learningdevelopment.completion.infrastructure.LdCompletionCaseRepository;
import com.primehr.learningdevelopment.plan.domain.*;
import com.primehr.learningdevelopment.plan.infrastructure.*;
import com.primehr.shared.audit.PrimeHrAuditService;
import com.primehr.shared.exception.*;
import com.primehr.succession.api.SuccessionDevelopmentDtos.*;
import com.primehr.succession.domain.*;
import com.primehr.succession.infrastructure.*;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.*;
import java.util.*;

@Service @Transactional
public class SuccessionDevelopmentServiceImpl implements SuccessionDevelopmentService{
 private final SuccessionDevelopmentPlanRepository plans;private final SuccessionDevelopmentSourceRepository sources;private final SuccessionDevelopmentMilestoneRepository milestones;private final SuccessionDevelopmentReviewRepository reviews;private final SuccessionPoolMembershipEventRepository events;private final SuccessionPoolDecisionRepository decisions;private final SuccessionCandidateRepository candidates;private final SuccessionReadinessPanelAssignmentRepository assignments;private final LdIndividualDevelopmentPlanRepository idps;private final LdIndividualDevelopmentPlanItemRepository idpItems;private final LdCompletionCaseRepository completions;private final PrimeHrAuditService audit;
 public SuccessionDevelopmentServiceImpl(SuccessionDevelopmentPlanRepository plans,SuccessionDevelopmentSourceRepository sources,SuccessionDevelopmentMilestoneRepository milestones,SuccessionDevelopmentReviewRepository reviews,SuccessionPoolMembershipEventRepository events,SuccessionPoolDecisionRepository decisions,SuccessionCandidateRepository candidates,SuccessionReadinessPanelAssignmentRepository assignments,LdIndividualDevelopmentPlanRepository idps,LdIndividualDevelopmentPlanItemRepository idpItems,LdCompletionCaseRepository completions,PrimeHrAuditService audit){this.plans=plans;this.sources=sources;this.milestones=milestones;this.reviews=reviews;this.events=events;this.decisions=decisions;this.candidates=candidates;this.assignments=assignments;this.idps=idps;this.idpItems=idpItems;this.completions=completions;this.audit=audit;}
 @Override @Transactional(readOnly=true)public List<PlanResponse>list(String a,String actor,PermissionDataScope scope){return plans.findByAgencyIdOrderByCreatedAtDesc(a).stream().filter(x->visible(a,x,actor,scope)).map(x->response(a,x,actor,scope)).toList();}
 @Override @Transactional(readOnly=true)public PlanResponse get(String a,String id,String actor,PermissionDataScope scope){var p=plan(a,id);access(a,p,actor,scope);return response(a,p,actor,scope);}
 @Override public PlanResponse create(String a,String decisionId,CreatePlanInput in,String actor,PermissionDataScope scope,String correlation){var d=decision(a,decisionId);var c=candidate(a,d.getCandidateId());panelAuthority(a,d.getAssessmentId(),c,actor,scope);check(d.getVersion(),in.decisionRecordVersion());if(d.getOutcome()!=SuccessionPoolDecision.Outcome.INCLUDED)throw new IllegalStateException("Only an included pool decision may have a succession development plan");if(d.getExpiresOn()!=null&&LocalDate.now(ZoneId.of("Asia/Manila")).isAfter(d.getExpiresOn()))throw new IllegalStateException("Expired pool membership cannot start a development plan");withinMembership(d,in.startsOn(),in.targetCompletionDate());if(plans.findByAgencyIdAndPoolDecisionId(a,decisionId).isPresent())throw new OptimisticConflictException("A development plan already exists for this pool decision");var p=plans.saveAndFlush(new SuccessionDevelopmentPlan(a,d,c,in.overallGoal(),in.startsOn(),in.targetCompletionDate(),in.nextReviewOn()));var event=events.saveAndFlush(SuccessionPoolMembershipEvent.activate(a,d,actor,Instant.now()));var out=response(a,p,actor,scope);record(a,"ACTIVATE_SUCCESSION_POOL_MEMBERSHIP",event,out,d.getRestrictedRationale(),correlation);record(a,"CREATE_SUCCESSION_DEVELOPMENT_PLAN",p,out,null,correlation);return out;}
 @Override public PlanResponse update(String a,String id,UpdatePlanInput in,String actor,PermissionDataScope scope,String correlation){var p=editable(a,id,actor,scope);check(p.getVersion(),in.recordVersion());withinMembership(decision(a,p.getPoolDecisionId()),in.startsOn(),in.targetCompletionDate());p.update(in.overallGoal(),in.startsOn(),in.targetCompletionDate(),in.nextReviewOn());p=plans.saveAndFlush(p);var out=response(a,p,actor,scope);record(a,"UPDATE_SUCCESSION_DEVELOPMENT_PLAN",p,out,null,correlation);return out;}
 @Override public PlanResponse addSource(String a,String id,SourceInput in,String actor,PermissionDataScope scope,String correlation){var p=editable(a,id,actor,scope);check(p.getVersion(),in.recordVersion());if(sources.existsByAgencyIdAndPlanIdAndSourceTypeAndSourceId(a,id,in.sourceType(),in.sourceId()))throw new OptimisticConflictException("Development source is already linked");SuccessionDevelopmentSource source=switch(in.sourceType()){case APPROVED_IDP_ITEM->idpSource(a,p,in.sourceId());case COMPLETED_LD_CASE->completionSource(a,p,in.sourceId());};sources.saveAndFlush(source);var out=response(a,p,actor,scope);record(a,"LINK_SUCCESSION_DEVELOPMENT_SOURCE",source,out,null,correlation);return out;}
 @Override public PlanResponse addMilestone(String a,String id,MilestoneInput in,String actor,PermissionDataScope scope,String correlation){var p=editable(a,id,actor,scope);check(p.getVersion(),in.recordVersion());if(in.dueDate().isBefore(p.getStartsOn())||in.dueDate().isAfter(p.getTargetCompletionDate()))throw new IllegalArgumentException("Milestone due date must fall within the plan period");if(milestones.existsByAgencyIdAndPlanIdAndDisplayOrder(a,id,in.displayOrder()))throw new OptimisticConflictException("Milestone display order already exists");var m=milestones.saveAndFlush(new SuccessionDevelopmentMilestone(a,id,in.title(),in.measurableOutcome(),in.dueDate(),in.displayOrder()));var out=response(a,p,actor,scope);record(a,"ADD_SUCCESSION_DEVELOPMENT_MILESTONE",m,out,null,correlation);return out;}
 @Override public PlanResponse updateMilestone(String a,String id,String milestoneId,MilestoneStatusInput in,String actor,PermissionDataScope scope,String correlation){var p=plan(a,id);panelAction(a,p,actor,scope);if(p.getStatus()!=SuccessionDevelopmentPlan.Status.ACTIVE)throw new IllegalStateException("Milestone progress may only be recorded for an active plan");var m=milestones.findByIdAndAgencyIdAndPlanId(milestoneId,a,id).orElseThrow(()->new ResourceNotFoundException("Development milestone not found"));check(m.getVersion(),in.recordVersion());m.updateStatus(in.status(),in.evidenceReference(),in.employeeVisibleFeedback(),in.restrictedFeedback(),actor,Instant.now());milestones.saveAndFlush(m);var out=response(a,p,actor,scope);record(a,"UPDATE_SUCCESSION_DEVELOPMENT_MILESTONE",m,out,in.restrictedFeedback(),correlation);return out;}
 @Override public PlanResponse activate(String a,String id,VersionInput in,String actor,PermissionDataScope scope,String correlation){var p=editable(a,id,actor,scope);check(p.getVersion(),in.recordVersion());if(sources.findByAgencyIdAndPlanIdOrderByCreatedAtAsc(a,id).isEmpty())throw new IllegalStateException("At least one approved IDP or completed L&D source is required");if(milestones.findByAgencyIdAndPlanIdOrderByDisplayOrder(a,id).isEmpty())throw new IllegalStateException("At least one measurable milestone is required");p.activate(actor,Instant.now());p=plans.saveAndFlush(p);var out=response(a,p,actor,scope);record(a,"ACTIVATE_SUCCESSION_DEVELOPMENT_PLAN",p,out,null,correlation);return out;}
 @Override public PlanResponse acknowledge(String a,String id,AcknowledgmentInput in,String actor,String correlation){var p=plan(a,id);if(!p.getEmployeeNo().equalsIgnoreCase(actor))throw new AccessDeniedException("Only the candidate may acknowledge this development plan");check(p.getVersion(),in.recordVersion());p.acknowledge(actor,in.response(),Instant.now());p=plans.saveAndFlush(p);var out=response(a,p,actor,PermissionDataScope.OWN_RECORDS);record(a,"ACKNOWLEDGE_SUCCESSION_DEVELOPMENT_PLAN",p,out,in.response(),correlation);return out;}
 @Override public PlanResponse review(String a,String id,ReviewInput in,String actor,PermissionDataScope scope,String correlation){var p=plan(a,id);panelAction(a,p,actor,scope);check(p.getVersion(),in.recordVersion());if(p.getStatus()!=SuccessionDevelopmentPlan.Status.ACTIVE)throw new IllegalStateException("Only an active development plan may be reviewed");if(in.reviewDate().isBefore(p.getStartsOn())||in.reviewDate().isAfter(p.getTargetCompletionDate()))throw new IllegalArgumentException("Review date must fall within the plan period");int sequence=Math.toIntExact(reviews.countByAgencyIdAndPlanId(a,id)+1);var review=reviews.saveAndFlush(new SuccessionDevelopmentReview(a,id,sequence,in.reviewDate(),in.recommendation(),in.employeeVisibleSummary(),in.restrictedRationale(),actor,Instant.now(),in.nextReviewOn()));var out=response(a,p,actor,scope);record(a,"REVIEW_SUCCESSION_DEVELOPMENT_PLAN",review,out,in.restrictedRationale(),correlation);return out;}
 @Override public PlanResponse complete(String a,String id,VersionInput in,String actor,PermissionDataScope scope,String correlation){var p=plan(a,id);panelAction(a,p,actor,scope);check(p.getVersion(),in.recordVersion());var ms=milestones.findByAgencyIdAndPlanIdOrderByDisplayOrder(a,id);if(ms.isEmpty()||ms.stream().anyMatch(x->x.getStatus()!=SuccessionDevelopmentMilestone.Status.COMPLETED))throw new IllegalStateException("All development milestones must be completed");var rs=reviews.findByAgencyIdAndPlanIdOrderByReviewSequence(a,id);if(rs.isEmpty()||rs.get(rs.size()-1).getRecommendation()!=SuccessionDevelopmentReview.Recommendation.COMPLETE)throw new IllegalStateException("The latest periodic review must recommend completion");p.complete(actor,Instant.now());p=plans.saveAndFlush(p);var out=response(a,p,actor,scope);record(a,"COMPLETE_SUCCESSION_DEVELOPMENT_PLAN",p,out,null,correlation);return out;}
 @Override public PlanResponse membership(String a,String id,MembershipInput in,String actor,PermissionDataScope scope,String correlation){if(scope!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("Membership correction, expiry, removal, or reinstatement requires Agency Wide authority");var p=plan(a,id);if(p.getEmployeeNo().equalsIgnoreCase(actor))throw new AccessDeniedException("Candidate cannot decide their own membership status");if(in.eventType()==SuccessionPoolMembershipEvent.EventType.ACTIVATED)throw new IllegalArgumentException("Membership is already activated by the final decision");if(in.eventType()==SuccessionPoolMembershipEvent.EventType.REMOVED){var history=reviews.findByAgencyIdAndPlanIdOrderByReviewSequence(a,id);if(history.isEmpty()||history.get(history.size()-1).getRecommendation()!=SuccessionDevelopmentReview.Recommendation.REMOVE_FROM_POOL)throw new IllegalStateException("The latest periodic review must recommend removal before membership is removed");}var current=events.findFirstByAgencyIdAndPoolDecisionIdOrderByEventSequenceDesc(a,p.getPoolDecisionId()).orElseThrow(()->new ResourceNotFoundException("Membership history not found"));check(current.getVersion(),in.currentEventRecordVersion());if(in.effectiveOn().isBefore(current.getEffectiveOn()))throw new IllegalArgumentException("Membership event cannot predate the current lineage event");var d=decision(a,p.getPoolDecisionId());LocalDate expiry=in.eventType()==SuccessionPoolMembershipEvent.EventType.CORRECTED||in.eventType()==SuccessionPoolMembershipEvent.EventType.REINSTATED?in.expiresOn():current.getExpiresOn();if((in.eventType()==SuccessionPoolMembershipEvent.EventType.CORRECTED||in.eventType()==SuccessionPoolMembershipEvent.EventType.REINSTATED)&&(expiry==null||d.getExpiresOn()!=null&&expiry.isAfter(d.getExpiresOn())))throw new IllegalArgumentException("Membership cannot extend beyond the authorized final decision");if(in.eventType()==SuccessionPoolMembershipEvent.EventType.EXPIRED&&(current.getExpiresOn()==null||in.effectiveOn().isBefore(current.getExpiresOn())))throw new IllegalStateException("Membership cannot be marked expired before its expiry date");if(in.eventType()==SuccessionPoolMembershipEvent.EventType.REINSTATED&&d.getExpiresOn()!=null&&in.effectiveOn().isAfter(d.getExpiresOn()))throw new IllegalStateException("Expired membership requires a new authorized pool decision");var event=events.saveAndFlush(current.transition(in.eventType(),in.effectiveOn(),expiry,in.employeeVisibleReason(),in.restrictedRationale(),actor,Instant.now()));var out=response(a,p,actor,scope);record(a,"RECORD_SUCCESSION_MEMBERSHIP_"+in.eventType(),event,out,in.restrictedRationale(),correlation);return out;}

 private SuccessionDevelopmentSource idpSource(String a,SuccessionDevelopmentPlan p,String sourceId){var item=idpItems.findByIdAndAgencyId(sourceId,a).orElseThrow(()->new ResourceNotFoundException("IDP item not found"));var idp=idps.findByIdAndAgencyId(item.getPlanId(),a).orElseThrow(()->new ResourceNotFoundException("IDP not found"));if(idp.getStatus()!=LdIndividualDevelopmentPlan.Status.APPROVED)throw new IllegalStateException("Only an APPROVED IDP item may be linked");if(!idp.getEmployeeNo().equalsIgnoreCase(p.getEmployeeNo()))throw new AccessDeniedException("IDP item belongs to another employee");String fp=hash(item.getId(),item.getVersion(),item.getLearningNeedId(),item.getSourceFingerprint(),item.getDevelopmentObjective(),item.getSuccessMeasure(),item.getTargetDate());return new SuccessionDevelopmentSource(a,p.getId(),SuccessionDevelopmentSource.SourceType.APPROVED_IDP_ITEM,item.getId(),idp.getId(),item.getVersion(),fp,item.getDevelopmentObjective()+" | "+item.getSuccessMeasure(),item.getTargetDate());}
 private SuccessionDevelopmentSource completionSource(String a,SuccessionDevelopmentPlan p,String sourceId){var c=completions.findByIdAndAgencyId(sourceId,a).orElseThrow(()->new ResourceNotFoundException("L&D completion not found"));if(c.getStatus()!=LdCompletionCase.Status.COMPLETED)throw new IllegalStateException("Only a finalized COMPLETED L&D case may be linked");if(!c.getEmployeeNo().equalsIgnoreCase(p.getEmployeeNo()))throw new AccessDeniedException("L&D completion belongs to another employee");return new SuccessionDevelopmentSource(a,p.getId(),SuccessionDevelopmentSource.SourceType.COMPLETED_LD_CASE,c.getId(),c.getTrainingOrderId(),c.getVersion(),c.getCompletionFingerprint(),c.getDecisionReason(),c.getCompletionDate());}
 private PlanResponse response(String a,SuccessionDevelopmentPlan p,String actor,PermissionDataScope scope){boolean own=p.getEmployeeNo().equalsIgnoreCase(actor);boolean privileged=!own&&(scope==PermissionDataScope.AGENCY_WIDE||assigned(a,p.getAssessmentId(),actor));var ss=sources.findByAgencyIdAndPlanIdOrderByCreatedAtAsc(a,p.getId()).stream().map(x->new SourceResponse(x.getId(),x.getSourceType().name(),x.getSourceId(),x.getSourceParentId(),x.getSourceVersion(),x.getSourceFingerprint(),x.getSourceSummary(),x.getSourceDate())).toList();var ms=milestones.findByAgencyIdAndPlanIdOrderByDisplayOrder(a,p.getId()).stream().map(x->new MilestoneResponse(x.getId(),x.getVersion(),x.getTitle(),x.getMeasurableOutcome(),x.getDueDate(),x.getDisplayOrder(),x.getStatus().name(),x.getEvidenceReference(),x.getEmployeeVisibleFeedback(),privileged?x.getRestrictedFeedback():null,privileged?x.getUpdatedByActor():null,x.getStatusUpdatedAt())).toList();var rs=reviews.findByAgencyIdAndPlanIdOrderByReviewSequence(a,p.getId()).stream().map(x->new ReviewResponse(x.getId(),x.getReviewSequence(),x.getReviewDate(),x.getRecommendation().name(),x.getEmployeeVisibleSummary(),privileged?x.getRestrictedRationale():null,privileged?x.getReviewedBy():null,x.getReviewedAt(),x.getNextReviewOn())).toList();var es=events.findByAgencyIdAndPoolDecisionIdOrderByEventSequence(a,p.getPoolDecisionId()).stream().map(x->new MembershipResponse(x.getId(),x.getVersion(),x.getPreviousEventId(),x.getEventSequence(),x.getEventType().name(),x.getResultingStatus().name(),x.getEffectiveOn(),x.getExpiresOn(),x.getEmployeeVisibleReason(),privileged?x.getRestrictedRationale():null,privileged?x.getRecordedBy():null,x.getRecordedAt())).toList();return new PlanResponse(p.getId(),p.getVersion(),p.getSeriesId(),p.getPlanVersion(),p.getPoolDecisionId(),p.getAssessmentId(),p.getCandidateId(),p.getEmployeeNo(),p.getEmployeeName(),p.getTargetPositionName(),p.getReadinessLevelCode(),p.getOverallGoal(),p.getStartsOn(),p.getTargetCompletionDate(),p.getNextReviewOn(),p.getStatus().name(),p.getAcknowledgmentStatus().name(),p.getAcknowledgmentResponse(),p.getAcknowledgedAt(),privileged?p.getActivatedBy():null,p.getActivatedAt(),privileged?p.getCompletedBy():null,p.getCompletedAt(),ss,ms,rs,es);}
 private SuccessionDevelopmentPlan editable(String a,String id,String actor,PermissionDataScope scope){var p=plan(a,id);panelAction(a,p,actor,scope);if(p.getStatus()!=SuccessionDevelopmentPlan.Status.DRAFT)throw new IllegalStateException("Only a draft succession development plan may be changed");return p;}
 private void panelAction(String a,SuccessionDevelopmentPlan p,String actor,PermissionDataScope scope){if(p.getEmployeeNo().equalsIgnoreCase(actor))throw new AccessDeniedException("Candidate cannot perform panel action on their own development plan");if(scope==PermissionDataScope.AGENCY_WIDE)return;if(scope!=PermissionDataScope.ASSIGNED_RECORDS||!assigned(a,p.getAssessmentId(),actor))throw new AccessDeniedException("Development plan is not assigned to the current panel member");}
 private void panelAuthority(String a,String assessment,SuccessionCandidate c,String actor,PermissionDataScope scope){if(c.getEmployeeNo().equalsIgnoreCase(actor))throw new AccessDeniedException("Candidate cannot create their own succession development plan");if(scope==PermissionDataScope.AGENCY_WIDE)return;if(scope!=PermissionDataScope.ASSIGNED_RECORDS||!assigned(a,assessment,actor))throw new AccessDeniedException("Development plan is not assigned to the current panel member");}
 private boolean visible(String a,SuccessionDevelopmentPlan p,String actor,PermissionDataScope scope){return p.getEmployeeNo().equalsIgnoreCase(actor)||scope==PermissionDataScope.AGENCY_WIDE||scope==PermissionDataScope.ASSIGNED_RECORDS&&assigned(a,p.getAssessmentId(),actor);}
 private void access(String a,SuccessionDevelopmentPlan p,String actor,PermissionDataScope scope){if(!visible(a,p,actor,scope))throw new AccessDeniedException("Development plan is outside the permitted data scope");}
 private boolean assigned(String a,String assessment,String actor){return assignments.findByAgencyIdAndAssessmentIdOrderByMemberRole(a,assessment).stream().anyMatch(x->x.getEmployeeNo().equalsIgnoreCase(actor)&&x.getStatus()==SuccessionReadinessPanelAssignment.Status.ASSIGNED);}
 private SuccessionDevelopmentPlan plan(String a,String id){return plans.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Succession development plan not found"));}private SuccessionPoolDecision decision(String a,String id){return decisions.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Succession pool decision not found"));}private SuccessionCandidate candidate(String a,String id){return candidates.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Succession candidate not found"));}
 private static void check(long actual,Long expected){if(expected==null||actual!=expected)throw new OptimisticConflictException("Record changed; reload and retry");}
 private static void withinMembership(SuccessionPoolDecision d,LocalDate starts,LocalDate target){if(starts.isBefore(d.getEffectiveFrom())||d.getExpiresOn()!=null&&target.isAfter(d.getExpiresOn()))throw new IllegalArgumentException("Development plan must remain within the authorized pool membership period");}
 private void record(String a,String action,com.primehr.rsp.domain.RspAuditedEntity entity,Object after,String reason,String correlation){audit.record(a,action,entity.getClass().getSimpleName(),entity.getId(),null,entity.getVersion(),null,after,reason,correlation);}
 private static String hash(Object...parts){try{var md=MessageDigest.getInstance("SHA-256");for(Object p:parts){md.update(String.valueOf(p).getBytes(StandardCharsets.UTF_8));md.update((byte)'|');}return java.util.HexFormat.of().formatHex(md.digest());}catch(Exception e){throw new IllegalStateException(e);}}
}
